xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&display=swap');

.xt-root {
  /* 深色磨砂透感背景 */
  --xt-bg: rgba(15, 10, 15, 0.65);
  --xt-text: #ffffff;
  --xt-text-sub: #dddddd;
  --xt-text-muted: #888888;

  /* 恋爱主题色：淡粉色 */
  --xt-accent: #ff99bb;      
  --xt-accent-bg: rgba(255, 153, 187, 0.15);
  --xt-border: rgba(255, 255, 255, 0.2);
  --xt-glow-color: rgba(255, 153, 187, 0.5); /* 为 .glow 动画设置发光色 */

  --xt-radius: 4px; 
  --xt-font: 'Share Tech Mono', monospace, sans-serif;

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  border: 1px solid var(--xt-border);
  box-shadow: inset 0 0 30px rgba(0,0,0,0.3), 0 8px 32px rgba(0,0,0,0.4);
  letter-spacing: 1px;
}

/* 顶部文字 */
.xt-text-topHeader {
  color: var(--xt-accent);
  font-size: 10px;
  letter-spacing: 3px;
  border-bottom: 1px dashed var(--xt-border);
  padding-bottom: 5px;
}
.xt-text-topHeader::before { content: "♥ "; animation: pulse 1s infinite; }

/* 弹幕区 */
.xt-marquee { mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent); margin-bottom: 2px; }
.xt-marquee-inner { font-size: 11px; color: rgba(255,255,255,0.6); white-space: pre !important; }
.xt-marquee:nth-of-type(2) .xt-marquee-inner { color: var(--xt-accent); text-shadow: 0 0 5px rgba(255,153,187,0.3); } 
.xt-marquee.fast .xt-marquee-inner { animation-duration: 6s !important; }
.xt-marquee.mid .xt-marquee-inner { animation-duration: 9s !important; }
.xt-marquee.slow .xt-marquee-inner { animation-duration: 12s !important; }

/* 头像：全彩 + 粉色边框 */
.xt-duo-avatar {
  border-radius: 50% !important;
  border: 2px solid var(--xt-accent);
  box-shadow: 0 0 10px rgba(255,153,187,0.3);
}
.xt-duo-heart { color: var(--xt-accent); font-size: 16px; }

/* 暴力清除默认左侧粗边框和背景 */
.xt-section-body, .xt-collapse-body, .xt-list {
  border-left: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding-left: 0 !important;
}

/* 重新定义标题块样式 */
.xt-section-title, .xt-collapse-header {
  border-left: 2px solid var(--xt-accent) !important;
  border-radius: 0 !important;
  padding-left: 8px !important;
  font-size: 12px;
  color: #eeeeee;
  background: linear-gradient(90deg, rgba(255,153,187,0.1), transparent) !important;
  margin-top: 5px;
  margin-bottom: 5px;
}

/* 正文与数据网格条 */
.xt-section-body { color: #dddddd; font-size: 13px; }
.xt-bar-track { background: rgba(255,255,255,0.1); border-radius: 2px; height: 6px; }
.xt-bar-fill { background: #ffffff; border-radius: 2px; }
.xt-grid-bar:nth-child(3) .xt-bar-fill { background: var(--xt-accent); box-shadow: 0 0 8px var(--xt-accent); }

/* 列表与气泡 */
.xt-list-item { border-bottom: 1px solid rgba(255,255,255,0.05); color: #cccccc; font-size: 12px; }
.xt-list-check { display: none; }
.xt-list-item::before { content: "♥ "; color: var(--xt-accent); font-size: 10px; }

.xt-bubble-body {
  border-radius: 8px !important;
  font-size: 12px;
  background: rgba(255,255,255,0.05) !important;
  border: 1px solid rgba(255,255,255,0.1) !important;
  color: #cccccc !important;
}
.xt-bubble-left .xt-bubble-body { border-left: 2px solid #888 !important; }
.xt-bubble-right .xt-bubble-body { border-right: 2px solid var(--xt-accent) !important; color: #ffffff !important; }

/* 真实心声区块发光高亮 */
.xt-section:last-of-type .xt-section-title {
  color: var(--xt-accent) !important;
  border-left: 3px solid #ff4d88 !important;
  background: linear-gradient(90deg, rgba(255,77,136,0.2), transparent) !important;
}
.xt-section:last-of-type .xt-section-body {
  font-style: italic;
  border: 1px dashed rgba(255, 153, 187, 0.4);
  padding: 12px;
  background: rgba(255, 153, 187, 0.08);
  border-radius: 6px;
  color: #ffffff;
  text-shadow: 0 0 5px rgba(255, 153, 187, 0.3);
  margin-bottom: 10px;
}

/* 底部随机动态标签 */
.xt-tag { 
  background: rgba(255, 153, 187, 0.15); 
  border: 1px solid var(--xt-accent); 
  color: #ffffff; 
  font-size: 11px; 
  border-radius: 4px;
}

/* 爱心粒子特效微调：让爱心呈现半透明粉色，更梦幻 */
.xt-particles-hearts .xt-particle {
  color: rgba(255, 153, 187, 0.6) !important;
  text-shadow: 0 0 5px rgba(255, 153, 187, 0.8);
}
/* 隐藏双头像下的名字，只保留头像和爱心 */
.xt-duo-name {
  display: none !important;
}

xinshengLayout:
# --- 恋爱全息终端 v9.2 (视角修正版) ---
# 💖 增加爱心上浮粒子背景
@particles hearts 15

@text topHeader .pulse

# 弹幕监控流
@marquee bullets1 .fast
@marquee bullets2 .slow
@marquee bullets3 .mid

@spacer 10

# 观测主体与心动率 (带发光特效)
@duo charImage charName userImage userName .fadeInDown
@bar syncRate "SYNC RATE [%]" .glow

@spacer 10

# 恋爱分析矩阵（宿主状态）
@section HOST STATUS [Ⅰ] .fadeInUp.delay100
  charStatus

@grid 3 .stagger
  heartbeat:bar "HEART"
  sweetness:bar "SWEET"
  oocIndex:bar "OOC"

# 目标弱点扫描与系统建议
@section TARGET WEAKNESS SCAN [Ⅱ] .fadeInUp.delay200
  weakness

@section SYSTEM ADVICE [Ⅲ] .fadeInUp.delay200
  sysAdvice

# 任务列表
@collapse "ACTIVE TASKS [Ⅳ]" 1 .fadeInUp.delay300
@list
  task1
  task2
  task3
@endcollapse

# 脑内频段截获 (系统 vs 宿主)
@collapse "INTERCEPTED AUDIO [Ⅴ]" 2 .fadeInUp.delay400
@bubbles
  msg1:left
  msg2:right
  msg3:left
  msg4:right
  msg5:left
@endcollapse

@spacer 10

# ⚠️ 宿主真实心声直接展示
@section TRUE FEELINGS [Ⅵ] .fadeInUp.delay500
  trueVoice

@bar heRate "HE结局预测达成率 [%]" .breathe

# 动态状态标签
@tags .fadeIn.delay600
  tag1
  tag2
  tag3

xinshengCustomCss:
.xt-root {
  --xt-bg: #000;
  --xt-text: #fff;
  --xt-text-sub: #ccc;
  --xt-text-muted: #ff5599;
  --xt-accent: #ff5599;
  --xt-accent-bg: rgba(255,85,153,0.1);
  --xt-border: rgba(255,85,153,0.3);
  --xt-radius: 12px;
  --xt-font: -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;

  background-image: url("https://imgbed.heliar.top/file/1776214157995_IMG_20260415_084906.jpg");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  position: relative;
  max-height: 75vh;
  overflow-y: auto !important;
  padding: 0;
}
.xt-root::before {
  content: "";
  position: absolute;
  top:0;left:0;right:0;bottom:0;
  background: rgba(0,0,0,0.15);
  z-index: 0;
  pointer-events: none;
}
.xt-content { position: relative; z-index: 1; }
.xt-root::-webkit-scrollbar {width:4px;}
.xt-root::-webkit-scrollbar-thumb {background:#ff5599; border-radius:4px;}
.xt-root::-webkit-scrollbar-track {background:rgba(0,0,0,0.3);}

.xt-header {
  position: relative;
  display: flex;
  align-items: center;
  padding: 8px 14px;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(6px);
  margin-bottom: 10px;
  z-index: 2;
}
.xt-header::after {
  content: "一顆心 可以衹有我嗎";
  margin-left: auto;
  font-size: 11px;
  color: #ff5599;
  white-space: nowrap;
}

.xt-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid #ff5599;
  margin-right: -2px;
  flex-shrink: 0;
}

.xt-name {
  font-size: 14px;
  color: #fff;
  line-height: 1.2;
  position: relative;
  margin-top: 0px;
}
.xt-name::after {
  content: "已关注";
  margin-left: 8px;
  background: #000;
  color: #ff5599;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 20px;
}

.xt-section {
  background: rgba(0,0,0,0.5);
  border-radius: 12px;
  padding: 14px;
  margin: 0 14px 10px;
  border: 1px solid var(--xt-border);
  z-index: 2;
}
.xt-section-title {
  font-size: 12px;
  color: #ff5599;
  letter-spacing: 1px;
  margin:0;
}
.xt-section-body {
  font-size: 14px;
  line-height: 1.6;
  color: #fff;
  margin-top: 6px;
}

.xt-section-3 .xt-section-body div {
  margin: 6px 0;
  padding: 4px 0;
}
.xt-section-3 .xt-section-body div:nth-child(odd) {
  color: #ccc;
  font-size: 13px;
}
.xt-section-3 .xt-section-body div:nth-child(even) {
  color: #fff;
  font-size: 14px;
  padding-left: 10px;
  border-left: 2px solid #ff5599;
  background: rgba(255,85,153,0.08);
  border-radius: 0 6px 6px 0;
  padding-bottom: 8px;
  margin-bottom: 8px;
  position: relative;
}
.xt-section-3 .xt-section-body div:nth-child(even)::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 1px;
  background: rgba(255,85,153,0.2);
}
.xt-section-3 .xt-section-body div:nth-last-child(1)::after {
  display: none;
}

.xt-grid {
  gap:10px;
  margin:0 14px 10px;
  position: relative;
  z-index:2;
}
.xt-grid-stat {
  background:rgba(0,0,0,0.5);
  border:1px solid var(--xt-border);
  border-radius:12px;
  padding:14px;
  text-align:left;
}
.xt-grid-stat-label {font-size:12px;color:#ff5599;}
.xt-grid-stat-value {font-size:14px;color:#fff;line-height:1.5}

.xt-section-4 .xt-section-body div {
  display:flex;
  align-items:center;
  gap:8px;
  margin-bottom:6px;
  color:#fff;
}
.xt-section-4 .xt-section-body div::before {
  content:"✓";
  width:16px; height:16px;
  border:1px solid #ff5599;
  border-radius:4px;
  color:#ff5599;
  font-size:12px;
  display:flex;
  align-items:center;
  justify-content:center;
  flex-shrink:0;
}

.xt-section-5 { margin-bottom:14px; }

