.xt-text:nth-of-type(8)::before { background: url('https://i.postimg.cc/gJmVCLGT/IMG-5184.jpg') center/cover !important; }
.xt-text:nth-of-type(9)::before { background: url('https://i.postimg.cc/x1mLq3CK/IMG-5185.jpg') center/cover !important; }

.xt-text:nth-of-type(4):active ~ .xt-text:nth-of-type(n+6),
.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(n+6),
.xt-text:nth-of-type(n+6):hover {
    opacity: 1 !important;
    transform: translateY(0) !important;
}

